#include <stdio.h>



int main(void)
{
    int a[] = {4, 1, 3, 2};
    for (int i = 0; i < 3; i++) {
        if (a[i] > a[i + 1]) {
            int t = a[i];
            a[i] = a[i + 1];
            a[i + 1] = t;
        }
    }
    printf("%d %d %d %d\n", a[0], a[1], a[2], a[3]);
    return 0;
}

#include <stdio.h>



int main(void)
{
    int a[] = {3, 2, 1};
    int smallest = 0;
    for (int i = 1; i < 3; i++) {
        if (a[i] < a[smallest]) {
            smallest = i;
        }
    }
    int t = a[0];
    a[0] = a[smallest];
    a[smallest] = t;
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return 0;
}

#include <stdio.h>



int main(void)
{
    int a[] = {2, 4, 6, 1};
    int key = a[3], position = 3, shifts = 0;
    while (position > 0 && a[position - 1] > key) {
        a[position] = a[position - 1];
        position--;
        shifts++;
    }
    a[position] = key;
    printf("%d\n", shifts);
    return 0;
}

